// actions.js
'use server';
import { z } from 'zod';

const schema = z.object({
  email: z.string().email(),
});

export async function submitAction(prevState, formData) {
  const result = schema.safeParse({ email: formData.get('email') });
  if (!result.success) {
    return { errors: result.error.flatten().fieldErrors };
  }
  return { success: true };
}

